let connected = false;
let tries = 0;

do {
  tries++;
  console.log('Attempt: ' + tries + ' — checking...');
  if (tries === 2) connected = true;
} while (!connected && tries < 5);

if (connected) {
  console.log('Connected after ' + tries + ' attempt(s)');
} else {
  console.log('Connection failed');
}

