let success = false;
let count = 0;
const MAX = 10;

while (!success && count < MAX) {
  count++;
  console.log('Try:', count);
  if (count === 4) success = true;
}

if (success) {
  console.log('Succeeded on try ' + count);
} else {
  console.log('Hit limit after ' + MAX + ' tries');
}
